let jsonData = pm.response.json() // Parse the JSON response body
let bookID = jsonData.ID; // Extract the book ID from the response
let req = JSON.parse(pm.request.body.raw) // Parse the request body as JSON, to get the aisle values from the request body.

// Store the book ID in a collection variable for future use
pm.environment.set("bookID", bookID);

// Genrate the expected book ID value based on the ISBN and aisle values from the request body.
function genrateBookID(){
    let expect_val = req.isbn + req.aisle
    console.log(expect_val)
    return expect_val; // Return the expected book ID value.
}


function cleanUpScript(){
    let book_ID = genrateBookID()
    pm.environment.set("bookID", book_ID) // Set the book ID as an environment variable so the next **Delete Book** request can reuse it without conflicts with other tests.
    pm.execution.setNextRequest("Delete Book")

    try{
        pm.response.to.have.status(200);
        pm.expect(jsonData).have.property("Msg")
        pm.expect(jsonData.Msg).to.equal("successfully added");
    }
    catch(err){
        if(jsonData.Msg.include("Book Already Exists")){
            cleanUpScript()
        }
    }
    
};

pm.test("Headers cookies", function (){
    pm.response.to.have.header("Content-Type");
    pm.expect(pm.response.headers.get("Content-Type")).to.equal("application/json;charset=UTF-8");
})


pm.test("check the responsetime and responsetext", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000); // less than 2 seconds
    pm.expect(pm.response.text()).to.include("successfully added")
})

